  };
  const tau = 2 * Math.PI, mod = (n, d) => ((n % d) + d) % d;
  const fmt = n => n.toFixed(2);
  let seed = 9714;
  const random = () => ((seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0) / 4294967296);
