  for (const [x,y,s] of locks) {
    const g = make('g', {transform:`translate(${x} ${y}) rotate(${between(-25,21)}) scale(${s})`}, $('curls'));
    make('path', {d:'M-6 0Q-2-5 2-3Q7-2 5 2Q3 4 0 2',fill:'none',stroke:'#ae7668','stroke-opacity':between(.23,.44),'stroke-width':1.3,'stroke-linecap':'round'}, g);
