  }

  // Repeat seamless strips of hand-shaped vegetation under the stationary hills.
  const width = 1440;
  const strips = [];
  function strip(id, count, rate, draw) {
    const root = $(id), key = id + 'Tile';
    const tile = make('g', {id:key}, root);
    for (let i=0; i<count; i++) draw(tile, (i + random()) * width / count);
    make('use', {href:'#'+key,x:width}, root);
