  }
  function grass(tile, x, y, scale, color, flowers) {
    const tilt = between(-20,22);
    const g = make('g', {transform:`translate(${fmt(x)} ${fmt(y)}) rotate(${fmt(tilt)}) scale(${fmt(scale)})`}, tile);
    make('path', {d:'M0 0Q-4-8-11-13Q-3-11 1-2Q-2-13-1-23Q3-13 3-3Q6-13 15-16Q8-9 5 0Z',fill:color}, g);
