  const point = (x,y) => `${fmt(x)} ${fmt(y)}`;
  function drawLeg(leg, cycle, dx, dy, angle) {
    const phase = mod(cycle - leg.beat, 1);
    let travel, lift = 0, roll = 0;
    if (phase < contact) {
      travel = stride * (.5 - phase / contact);
    } else {
      const u = (phase-contact)/(1-contact);
      // Hermite swing keeps horizontal velocity continuous at toe-off and landing.
      travel = -stride/2 + stride*(3*u*u-2*u*u*u)
        - stride*(1-contact)/contact*u*(1-u)*(1-2*u);
      lift = (leg.hind?23:27) * Math.pow(Math.sin(Math.PI*u),1.6);
      roll = 23*Math.sin(tau*u)*Math.sin(Math.PI*u);
    }
    const ax = leg.x + travel + (leg.hind ? -4 : 3);
    const ay = leg.floor - 8.7 - lift;
    const c = Math.cos(angle), s = Math.sin(angle);
    const hx = 210 + (leg.x-210)*c - (leg.y-170)*s + dx;
    const hy = 170 + (leg.x-210)*s + (leg.y-170)*c + dy;

    // Two-bone IK: the foreleg flexes forward at the knee, the hind leg back at the hock.
    const L1 = leg.hind ? 62 : 61, L2 = 60;
    const vx = ax-hx, vy = ay-hy, distance = Math.hypot(vx,vy);
    const ux = vx/distance, uy = vy/distance;
    const d = Math.min(distance,L1+L2-.001);
    const along = (L1*L1-L2*L2+d*d)/(2*d);
    const bend = Math.sqrt(Math.max(0,L1*L1-along*along))*(leg.hind?-1:1);
    const kx = hx + ux*along + uy*bend, ky = hy + uy*along - ux*bend;
    const l1 = Math.hypot(kx-hx,ky-hy), l2 = Math.hypot(ax-kx,ay-ky);
    const n1x = -(ky-hy)/l1, n1y = (kx-hx)/l1;
    const n2x = -(ay-ky)/l2, n2y = (ax-kx)/l2;
    const nm = Math.hypot(n1x+n2x,n1y+n2y);
    const nx = (n1x+n2x)/nm, ny = (n1y+n2y)/nm;
    const off = (x,y,nx,ny,w) => point(x+nx*w,y+ny*w);
    const h = w => off(hx,hy,n1x,n1y,w);
    const q = w => off(hx*.49+kx*.51,hy*.49+ky*.51,n1x,n1y,w);
    const k = w => off(kx,ky,nx,ny,w);
    const b = w => off(kx*.46+ax*.54,ky*.46+ay*.54,n2x,n2y,w);
    const a = w => off(ax,ay,n2x,n2y,w);
    const w = leg.hind ? 15 : 12;
    leg.shape.setAttribute('d',`M${h(w)} Q${q(w*.8)} ${k(5.7)} Q${b(3.5)} ${a(4)}
      L${a(-4.4)} Q${b(-3.2)} ${k(-5.4)} Q${q(-w*.64)} ${h(-w)}Z`);
    leg.shine.setAttribute('d',`M${q(5.7)} Q${k(4.2)} ${b(2.05)} T${a(2.35)}`);
    leg.toes.setAttribute('transform',`translate(${fmt(ax)} ${fmt(ay)}) rotate(${fmt(roll)})`);
    leg.shadow.setAttribute('cx',fmt(ax+2));
    leg.shadow.setAttribute('opacity',fmt(.79-lift*.024));
  }

  const body = $('body'), head = $('head'), tail = $('tail'), eye = $('eye');
  const nearEar = $('nearEar'), farEar = $('farEar'), tassels = $('tassels');
  const start = performance.now();
  function frame(now) {
    const time = (now-start)/1000, cycle = time/period, wave = tau*cycle;
    const dx = 1.65*Math.sin(wave-.5);
    const dy = 1.8*Math.cos(2*wave+.4) + .5*Math.sin(wave);
    const pitch = .9*Math.sin(wave+.6) + .34*Math.sin(2*wave);
    body.setAttribute('transform',`translate(${fmt(dx)} ${fmt(dy)}) rotate(${fmt(pitch)} 210 170)`);
    head.setAttribute('transform',`rotate(${fmt(-.7*pitch + 1.35*Math.sin(2*wave-.8))} 340 64)`);
    tail.setAttribute('transform',`rotate(${fmt(5*Math.sin(wave-.5)+2*Math.sin(time*2.3))} 94 156)`);
    nearEar.setAttribute('transform',`rotate(${fmt(2.1*Math.sin(wave-.7)+1.25*Math.sin(time*4.2))} 329 24)`);
    farEar.setAttribute('transform',`rotate(${fmt(2.8*Math.sin(wave+1.1))} 353 23)`);
    tassels.setAttribute('transform',`rotate(${fmt(6.8*Math.sin(2*wave-1.15)+2*Math.sin(wave))} 343 110)`);
    const blink = mod(time+2.2,5.6);
    const open = blink < .17 ? 1-.91*Math.pow(Math.sin(Math.PI*blink/.17),1.45) : 1;
    eye.setAttribute('transform',`translate(0 ${fmt(44*(1-open))}) scale(1 ${fmt(open)})`);
    $('bodyShadow').setAttribute('cx',fmt(210+dx*2));
    for (const leg of legs) drawLeg(leg,cycle,dx,dy,pitch*Math.PI/180);
    for (const {root,rate} of strips) root.setAttribute('transform',`translate(${fmt(-mod(time*trailSpeed*rate,width))} 0)`);
    requestAnimationFrame(frame);
  }
  frame(start);
})();
</script>
